        page = apply_query(tasks, TaskQuery(sort="title"), NOW)
        assert [t.id for t in page.items] == [2, 1, 3]

    def test_sort_descending(self):
        tasks = [_task(1, "Apple"), _task(2, "Banana")]
        page = apply_query(tasks, TaskQuery(sort="title", descending=True), NOW)
        assert [t.id for t in page.items] == [2, 1]

    def test_sort_by_due_at_none_last(self):
        tasks = [
            _task(1, due_at=None),
            _task(2, due_at=NOW + timedelta(hours=1)),
            _task(3, due_at=NOW - timedelta(hours=1)),
        ]
        page = apply_query(tasks, TaskQuery(sort="due_at"), NOW)
        assert [t.id for t in page.items] == [3, 2, 1]

    def test_sort_by_created_at(self):
        t1 = _task(1, created_at=NOW - timedelta(hours=2))
        t2 = _task(2, created_at=NOW - timedelta(hours=1))
        page = apply_query([t1, t2], TaskQuery(sort="created_at"), NOW)
        assert [t.id for t in page.items] == [1, 2]


class TestApplyQueryPagination:
    @pytest.fixture
    def tasks(self):
        return [_task(i, created_at=NOW - timedelta(hours=10 - i)) for i in range(1, 11)]

    def test_limit(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=3), NOW)
        assert len(page.items) == 3
        assert page.total == 10

    def test_offset(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=3, offset=8), NOW)
        assert len(page.items) == 2
        assert page.total == 10

    def test_has_more_true(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=5, offset=0), NOW)
        assert page.has_more is True

    def test_has_more_false(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=5, offset=5), NOW)
        assert page.has_more is False

    def test_offset_beyond_total(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=5, offset=20), NOW)
        assert page.items == []
        assert page.has_more is False


